// IdentityServer is the server API for Identity service.
// All implementations must embed UnimplementedIdentityServer
// for forward compatibility.
//
// identity: único contenedor que emite sesiones y decide roles/permisos.
// Spec completa: identity/SPEC.md. Cambios aquí son SOLO aditivos (ADR 0004):
// los números de campo ya publicados nunca se reutilizan ni se cambian.
type IdentityServer interface {
	// ── Implementado (L1 + L4) ──
	Register(context.Context, *RegisterRequest) (*AuthResult, error)
	Login(context.Context, *LoginRequest) (*AuthResult, error)
	ValidateToken(context.Context, *ValidateTokenRequest) (*ValidateTokenResult, error)
	GetUserPermissions(context.Context, *GetUserPermissionsRequest) (*UserPermissions, error)
	RefreshToken(context.Context, *RefreshTokenRequest) (*AuthResult, error)
	// ── Objetivo (identity/SPEC.md §12) ──
	Logout(context.Context, *LogoutRequest) (*LogoutResult, error)
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResult, error)
	RevokeSession(context.Context, *RevokeSessionRequest) (*RevokeSessionResult, error)
	ChangePassword(context.Context, *ChangePasswordRequest) (*SimpleResult, error)
	RequestPasswordReset(context.Context, *RequestPasswordResetRequest) (*SimpleResult, error)
	ConfirmPasswordReset(context.Context, *ConfirmPasswordResetRequest) (*SimpleResult, error)
	// Alta de comercio (autoservicio) y revisión por la plataforma (KYB)
	CreateBusiness(context.Context, *CreateBusinessRequest) (*CreateBusinessResult, error)
	ReviewBusiness(context.Context, *ReviewBusinessRequest) (*Tenant, error)
	GetTenant(context.Context, *GetTenantRequest) (*Tenant, error)
	ListTenants(context.Context, *ListTenantsRequest) (*ListTenantsResult, error)
	// Equipo del comercio
	InviteStaff(context.Context, *InviteStaffRequest) (*Invitation, error)
	AcceptInvitation(context.Context, *AcceptInvitationRequest) (*AuthResult, error)
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResult, error)
	DeactivateUser(context.Context, *DeactivateUserRequest) (*SimpleResult, error)
	// Solo servicios de confianza (notifications): contacto e idioma por id. Nunca expuesto por el gateway.
	GetUserContacts(context.Context, *GetUserContactsRequest) (*GetUserContactsResult, error)
	// Roles personalizados por comercio y asignación
	UpsertRole(context.Context, *UpsertRoleRequest) (*Role, error)
	ListRoles(context.Context, *ListRolesRequest) (*ListRolesResult, error)
	AssignRole(context.Context, *AssignRoleRequest) (*SimpleResult, error)
	// ── Modelo de acceso (ADR 0018, identity/SPEC.md §4). Solo aditivo. ──
	ListVerticals(context.Context, *ListVerticalsRequest) (*ListVerticalsResult, error)
	ListRoleTemplates(context.Context, *ListRoleTemplatesRequest) (*ListRoleTemplatesResult, error)
	GetAccessCatalog(context.Context, *GetAccessCatalogRequest) (*AccessCatalog, error)
	GetBusinessProfile(context.Context, *GetBusinessProfileRequest) (*BusinessProfile, error)
	UpdateBusinessProfile(context.Context, *UpdateBusinessProfileRequest) (*BusinessProfile, error)
	SetCapabilities(context.Context, *SetCapabilitiesRequest) (*BusinessProfile, error)
	UpsertBranch(context.Context, *UpsertBranchRequest) (*Branch, error)
	ListBranches(context.Context, *ListBranchesRequest) (*ListBranchesResult, error)
	DeactivateBranch(context.Context, *BranchRef) (*Branch, error)
	ReactivateBranch(context.Context, *BranchRef) (*Branch, error)
	UpdateMembership(context.Context, *UpdateMembershipRequest) (*UserSummary, error)
	ArchiveRole(context.Context, *ArchiveRoleRequest) (*SimpleResult, error)
	SuspendUser(context.Context, *SetUserStatusRequest) (*SimpleResult, error)
	ReactivateUser(context.Context, *SetUserStatusRequest) (*SimpleResult, error)
	ListInvitations(context.Context, *ListInvitationsRequest) (*ListInvitationsResult, error)
	RevokeInvitation(context.Context, *InvitationRef) (*SimpleResult, error)
	ResendInvitation(context.Context, *InvitationRef) (*Invitation, error)
	// Passkeys / WebAuthn
	BeginPasskeyRegistration(context.Context, *BeginPasskeyRegistrationRequest) (*PasskeyChallenge, error)
	FinishPasskeyRegistration(context.Context, *FinishPasskeyRegistrationRequest) (*SimpleResult, error)
	BeginPasskeyLogin(context.Context, *BeginPasskeyLoginRequest) (*PasskeyChallenge, error)
	FinishPasskeyLogin(context.Context, *FinishPasskeyLoginRequest) (*AuthResult, error)
	// Confirmación fuerte para operaciones sensibles (pagos de monto alto): token de un solo uso,
	// de vida corta, atado a (user, operation, amount). El servicio que ejecuta la operación lo CONSUME (ADR 0011).
	IssueStepUpChallenge(context.Context, *StepUpRequest) (*PasskeyChallenge, error)
	VerifyStepUp(context.Context, *VerifyStepUpRequest) (*StepUpToken, error)
	ConsumeStepUp(context.Context, *ConsumeStepUpRequest) (*ConsumeStepUpResult, error)
	mustEmbedUnimplementedIdentityServer()
}

